package com.hau.notification.infrastructure.persistence.entity;import com.hau.notification.domain.model.NotificationType;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="notifications") public class NotificationEntity{@Id private UUID id;@Column(name="user_id",nullable=false)private UUID userId;@Enumerated(EnumType.STRING)@Column(nullable=false,length=64)private NotificationType type;@Column(nullable=false,length=200)private String title;@Column(nullable=false,length=2000)private String content;@Column(name="reference_id",length=100)private String referenceId;@Column(name="reference_type",length=64)private String referenceType;@Column(name="is_read",nullable=false)private boolean read;@Column(name="read_at")private Instant readAt;@Column(name="created_at",nullable=false)private Instant createdAt;public NotificationEntity(){}public UUID getId(){return id;}public void setId(UUID v){id=v;}public UUID getUserId(){return userId;}public void setUserId(UUID v){userId=v;}public NotificationType getType(){return type;}public void setType(NotificationType v){type=v;}public String getTitle(){return title;}public void setTitle(String v){title=v;}public String getContent(){return content;}public void setContent(String v){content=v;}public String getReferenceId(){return referenceId;}public void setReferenceId(String v){referenceId=v;}public String getReferenceType(){return referenceType;}public void setReferenceType(String v){referenceType=v;}public boolean isRead(){return read;}public void setRead(boolean v){read=v;}public Instant getReadAt(){return readAt;}public void setReadAt(Instant v){readAt=v;}public Instant getCreatedAt(){return createdAt;}public void setCreatedAt(Instant v){createdAt=v;}}
